<script setup lang="ts">
import type { DashboardKpi } from '@/types/dashboard'
defineProps<{ item: DashboardKpi; loading: boolean }>()
const colors: Record<string,string> = { households:'primary', collected:'success', uncollected:'warning', revenue:'success', debt:'error', invoice_errors:'error' }
const icons: Record<string,string> = { households:'mdi-home-city-outline', collected:'mdi-home-check-outline', uncollected:'mdi-home-clock-outline', revenue:'mdi-cash-multiple', debt:'mdi-cash-remove', invoice_errors:'mdi-receipt-text-remove-outline' }
const money = (value:number) => new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(value)
</script>
<template><v-card class="dashboard-kpi pa-4 h-100" border rounded="xl"><v-skeleton-loader v-if="loading" type="list-item-avatar-two-line" /><template v-else><div class="d-flex justify-space-between ga-3"><div class="min-width-0"><div class="text-caption text-medium-emphasis mb-2">{{ item.label }} <v-tooltip activator="parent">So sánh cùng độ dài với kỳ ngay trước đó</v-tooltip></div><div class="text-h6 text-md-h5 font-weight-bold text-truncate">{{ item.format === 'currency' ? money(item.value) : new Intl.NumberFormat('vi-VN').format(item.value) }}</div></div><v-avatar :color="colors[item.key]" variant="tonal" rounded="lg"><v-icon :icon="icons[item.key]" /></v-avatar></div><div class="d-flex align-center ga-1 mt-3 text-caption" :class="item.trend === 'up' ? 'text-success' : item.trend === 'down' ? 'text-error' : 'text-medium-emphasis'"><v-icon :icon="item.trend === 'up' ? 'mdi-trending-up' : item.trend === 'down' ? 'mdi-trending-down' : 'mdi-minus'" size="17" /><span>{{ Math.abs(item.change_percent).toLocaleString('vi-VN') }}% so với kỳ trước</span></div></template></v-card></template>
